svg.script:
const note=document.getElementById("note"),retry=document.getElementById("retry");
retry.addEventListener("click",()=>location.reload());
function failed(){note.textContent="Could not open the page. Try again.";retry.hidden=false;}
if(!navigator.serviceWorker)failed();else navigator.serviceWorker.register("./sw.js?v=4bd850f3f19c",{scope:"./"}).then(()=>navigator.serviceWorker.ready).then(()=>{if(navigator.serviceWorker.controller)location.reload();else navigator.serviceWorker.addEventListener("controllerchange",()=>location.reload(),{once:true});}).catch(failed);
